import React, { useCallback, useRef, useState } from 'react';
import { HostEvent } from '@thoughtspot/visual-embed-sdk';
import { SearchEmbed, SpotterEmbed } from '@thoughtspot/visual-embed-sdk/react';
import { THOUGHTSPOT_MODEL_ID, VIEWPORT_LESS_TOP_HEADER } from '../config/thoughtspot';
import { useTier } from '../config/TierContext';
import { formatThoughtSpotEmbedError } from '../utils/thoughtspotErrors';

type TabId = 'stella' | 'explore';

const DARK = '#0C0C0C';
const DARK_2 = '#141414';
const BRAND_GREEN = '#22D472';

function TabCard({
  active,
  title,
  subtitle,
  onClick,
}: {
  active: boolean;
  title: string;
  subtitle: string;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      style={{
        flex: '1 1 160px',
        minWidth: 140,
        textAlign: 'left',
        padding: '1.25rem 1.35rem',
        borderRadius: 12,
        border: active ? `1px solid ${BRAND_GREEN}` : '1px solid rgba(255,255,255,0.12)',
        backgroundColor: active ? BRAND_GREEN : 'rgba(255,255,255,0.06)',
        color: active ? '#ffffff' : 'rgba(255,255,255,0.85)',
        cursor: 'pointer',
        transition: 'background-color 0.15s ease, border-color 0.15s ease',
      }}
    >
      <div style={{ fontWeight: 600, fontSize: 15, marginBottom: 4, letterSpacing: '-0.02em' }}>{title}</div>
      <div
        style={{
          fontSize: 13,
          fontWeight: 400,
          color: active ? 'rgba(255,255,255,0.8)' : 'rgba(255,255,255,0.45)',
        }}
      >
        {subtitle}
      </div>
    </button>
  );
}

function StellaUpgrade({ onUpgrade }: { onUpgrade: () => void }) {
  return (
    <div
      style={{
        backgroundColor: '#fff',
        borderRadius: 16,
        border: '1px solid #F3E6EA',
        padding: '3rem 2rem',
        textAlign: 'center',
        maxWidth: 480,
        margin: '2rem auto',
        boxShadow: '0 2px 24px rgba(0,0,0,0.10)',
      }}
    >
      <div style={{ fontSize: 32, marginBottom: 12 }}>✦</div>
      <h2 style={{ fontSize: 20, fontWeight: 700, color: '#0C0C0C', margin: '0 0 8px', letterSpacing: '-0.03em' }}>Meet Iris</h2>
      <p style={{ fontSize: 14, color: '#6B7280', lineHeight: 1.6, margin: '0 0 1.25rem' }}>
        Ask questions in plain English about your venue data. Upgrade to Pro to unlock Iris, your AI analyst.
      </p>
      <button
        type="button"
        onClick={onUpgrade}
        style={{
          backgroundColor: BRAND_GREEN,
          color: '#fff',
          border: 'none',
          padding: '10px 28px',
          borderRadius: 24,
          fontSize: 14,
          fontWeight: 600,
          cursor: 'pointer',
          letterSpacing: '-0.01em',
        }}
      >
        Upgrade to Pro
      </button>
    </div>
  );
}

export default function Analytics() {
  const [tab, setTab] = useState<TabId>('stella');
  const [selectedPrompt, setSelectedPrompt] = useState<string | undefined>(undefined);
  const { hiddenActions, disabledActions, spotterEnabled, setTier } = useTier();
  const spotterRef = useRef<any>(null);
  const searchRef = useRef<any>(null);

  const onError = useCallback((err: { data?: { errorMessage?: string }; message?: string }) => {
    console.error('[ThoughtSpot Analytics]', formatThoughtSpotEmbedError(err), err);
  }, []);

      const handleRefresh = () => {
    try {
      if (tab === 'stella') spotterRef.current?.trigger(HostEvent.Reload);
      else searchRef.current?.trigger(HostEvent.Reload);
    } catch (e) {
      console.warn('Reload trigger', e);
    }
  };

  return (
    <div
      style={{
        height: VIEWPORT_LESS_TOP_HEADER,
        display: 'flex',
        flexDirection: 'column',
        backgroundColor: DARK,
        overflow: 'hidden',
      }}
    >
      <div
        style={{
          flexShrink: 0,
          borderBottom: '1px solid rgba(255,255,255,0.08)',
        }}
      >
        {/* Compact header row: title left, refresh right */}
        <div style={{ backgroundColor: DARK, padding: '0.75rem 2rem', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div>
            <span style={{ fontSize: 10, fontWeight: 600, letterSpacing: '0.12em', textTransform: 'uppercase', color: BRAND_GREEN, marginRight: 12 }}>
              VisioLab
            </span>
            <span style={{ fontSize: 18, fontWeight: 700, color: '#ffffff', letterSpacing: '-0.02em' }}>
              Explore & Ask Iris
            </span>
          </div>
          <button
            type="button"
            onClick={handleRefresh}
            style={{
              padding: '7px 16px',
              borderRadius: 24,
              border: '1px solid rgba(255,255,255,0.2)',
              background: 'rgba(255,255,255,0.08)',
              color: '#ffffff',
              fontSize: 13,
              fontWeight: 500,
              cursor: 'pointer',
            }}
          >
            Refresh
          </button>
        </div>

        {/* Tab cards */}
        <div style={{ backgroundColor: DARK_2, padding: '0.6rem 2rem' }}>
          <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', alignItems: 'stretch' }}>
            <TabCard
              active={tab === 'stella'}
              title="◈ Iris"
              subtitle="Ask questions in plain English"
              onClick={() => { setTab('stella'); }}
            />
            <TabCard
              active={tab === 'explore'}
              title="Explore"
              subtitle="Build your own analysis"
              onClick={() => { setTab('explore'); }}
            />
          </div>
        </div>
      </div>

      {/* Content area — fills all remaining space, no page-level scroll */}
      <div
        style={{
          padding: '0.75rem 2rem',
          flex: '1 1 0',
          minHeight: 0,
          display: 'flex',
          flexDirection: 'column',
          backgroundColor: DARK,
          overflow: 'hidden',
        }}
      >
        {tab === 'stella' && !spotterEnabled ? (
          <StellaUpgrade onUpgrade={() => setTier('Pro')} />
        ) : (
          <div
            style={{
              flex: '1 1 0',
              minHeight: 0,
              position: 'relative',
              backgroundColor: '#ffffff',
              borderRadius: 16,
              overflow: 'hidden',
              boxShadow: '0 2px 32px rgba(0,0,0,0.5)',
            }}
          >
            <div style={{ position: 'absolute', inset: 0 }}>
              {tab === 'stella' && spotterEnabled && (
                <SpotterEmbed
                  key={selectedPrompt ?? 'stella-default'}
                  ref={spotterRef}
                  worksheetId={THOUGHTSPOT_MODEL_ID}
                  onError={onError}
                  hideSampleQuestions={!selectedPrompt}
                  {...(selectedPrompt ? { searchOptions: { searchQuery: selectedPrompt } } : {})}
                  style={{ width: '100%', height: '100%', border: 'none', display: 'block' }}
                />
              )}
              {tab === 'explore' && (
                <SearchEmbed
                  ref={searchRef}
                  dataSource={THOUGHTSPOT_MODEL_ID}
                  hiddenActions={hiddenActions}
                  disabledActions={disabledActions}
                  onError={onError}
                  style={{ width: '100%', height: '100%', border: 'none', display: 'block' }}
                />
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
